mapper.select:
select u.id as user_id, u.username, u.nickname, d.id as department_id, d.name as department_name, cm.joined_at, cm.status, case when dl.id is null then false else true end as department_leader from club_member cm inner join app_user u on u.id = cm.user_id inner join department d on d.id = cm.department_id left join department_leader dl on dl.user_id = cm.user_id and dl.department_id = cm.department_id
cm.department_id = #{departmentId}
order by u.id

mapper.update:
update club_member
set status = #{status}
where user_id = #{userId}
